const E=Engine,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={decisions:'<path d="m3 6 2 2 4-4M3 14l2 2 4-4M13 6h8M13 14h8M3 21h18"/>',overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 16v4a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-4"/>',applications:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9"/><circle cx="9" cy="7" r="4"/><path d="M16 3a4 4 0 0 1 0 8"/>',review:'<path d="m9 11 2 2 4-4M9 3H5v18h14V3h-4M9 2h6v4H9z"/>',territories:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',onboarding:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M8 2v4m8-4v4M8 11h8M8 15h5"/>',assistant:'<path d="M21 11a8 8 0 0 1-8 8H5l-4 3V11a10 10 0 0 1 20 0Z"/><path d="M7 10h.01M12 10h.01M17 10h.01"/>',rules:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor"/><circle cx="15" cy="17" r="3" fill="currentColor"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.overview}</svg>`;
const stores=[['ST-01','Bengaluru','560001',2019],['ST-02','Bengaluru','560034',2020],['ST-03','Bengaluru','560038',2021],['ST-04','Bengaluru','560066',2022],['ST-05','Bengaluru','560076',2023],['ST-06','Mysuru','570009',2021],['ST-07','Mysuru','570017',2024],['ST-08','Mangaluru','575001',2022],['ST-09','Hubballi-Dharwad','580020',2023],['ST-10','Belagavi','590001',2024]].map(([id,city,pin,year])=>({id,city,pin,year}));
const taskDefs=[['Funding verification','Finance · Verify available funds and any financing conditions.','Finance'],['Site assessment','Expansion · Check address, usable area, floor and site suitability.','Expansion'],['Conditional offer','Expansion · Prepare terms after funding and site checks.','Expansion'],['Acceptance and agreement','Legal · Record acceptance and signed agreement.','Legal'],['Fit-out and inventory','Operations · Complete fit-out, utilities, systems and opening stock.','Operations'],['Training completion','Training · Cover operations, inventory, billing and customer service.','Training'],['Opening readiness','Operations · Verify every prerequisite before opening.','Operations']];
let state={apps:[],territories:[],reference:null,settings:{...E.defaultPolicy},tasks:{},taskDates:{},audit:[],source:'Synthetic demo',warnings:[]},results=[],tab='overview',filter='',query='',chat=[],botContext=null,pendingChat=null,importPreview=null,storageOK=true;
function save(){state.messages=chat.slice(-100);state.botContext=botContext;try{localStorage.setItem('franchise-os-v1',JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;toast('Browser storage is unavailable or full. Export a workspace backup before leaving.');}document.querySelector('.local-badge').innerHTML=`<i></i> ${storageOK?'Saved in this browser':'Not saved · export a backup'}`;}
function calculate(){results=E.assess(state.apps,state.territories,stores,state.reference,state.settings);let old=E.assess(state.apps,state.territories,stores,state.reference,{});for(let r of results)r.legacyScore=old.find(a=>a.key===r.key)?.score;}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,5500);}
function audit(text){state.audit.unshift({at:new Date().toISOString(),text});state.audit=state.audit.slice(0,200);}
const decOrder=['Approve','Conditional','Redirect','Waitlist','Hold','Not eligible'],decColor={Approve:'green',Conditional:'blue',Redirect:'blue',Waitlist:'slate',Hold:'amber','Not eligible':'red'};
let decFilter='';
// First sentence carries the decision; the rest is supporting detail.
function reasonHtml(t){let m=String(t||'').match(/^(.*?\.)(\s+.*)?$/s);return m?`<span class="dec-lead">${esc(m[1])}</span>${m[2]?`<span class="dec-rest">${esc(m[2])}</span>`:''}`:esc(t);}
const dec=a=>a._dec||(a._dec=E.decision(a)),decKind=l=>String(l).startsWith('Hold')?'Hold':l,decRank=a=>{let i=decOrder.indexOf(decKind(dec(a).label));return i<0?decOrder.length:i;},decSort=(x,y)=>decRank(x)-decRank(y)||y.score-x.score;
function statusTag(a){let l=dec(a).label;return `<span class="tag ${decColor[decKind(l)]||'gray'}" title="Internal status: ${esc(a.status)}">${esc(l)}</span>`;}
function defaultTab(){return state.apps.length?'decisions':'overview';}
function heading(eyebrow,title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function pendingCount(){return state.apps.reduce((n,a)=>n+a.pending.length,0);}
function nav(){const labels={decisions:'Decisions',overview:'Overview',applications:'Applications',review:'Data review',territories:'Territories',onboarding:'Onboarding',assistant:'Right Pin bot',rules:'Scoring & rules'};$('#nav').innerHTML=Object.entries(labels).map(([k,v])=>`<button data-tab="${k}" class="nav-button ${tab===k?'active':''}">${icon(k)}${v}${k==='review'&&pendingCount()?`<span class="nav-count">${pendingCount()}</span>`:''}</button>`).join('');$('#crumb').textContent=labels[tab]||'Upload';$('#data-label').textContent=state.source.startsWith('Synthetic')?'Synthetic demo data':state.source;}
function render(){calculate();nav();const pages={decisions,overview,applications,review,territories,onboarding,assistant,rules,upload};$('#main').innerHTML='<div class="policy-banner"><strong>Industry-informed screening v2</strong> · Proposed policy, not an industry standard. Demo requirements: ₹'+esc(state.settings.minInvestment)+' lakh, '+esc(state.settings.minArea)+' sq ft, launch '+esc(state.settings.minLaunch)+'–'+esc(state.settings.targetLaunch)+' months.'+(presets[state.settings.preset]?' Preset: '+esc(presets[state.settings.preset].label)+'.':'')+((n=>n?' '+n+' geography rule'+(n===1?'':'s')+'.':'')(Object.keys(state.settings.tiers||{}).length+Object.keys(state.settings.cities||{}).length))+' <a href="#rules">Review assumptions</a></div>'+(pages[tab]||overview)();bindPage();}
function table(rows,compact=false){if(!rows.length)return `<div class="empty"><h2>No applications here yet</h2>Upload a workbook or change your filters.</div>`;return `<div class="table-wrap"><table><thead><tr><th>Applicant</th><th>Location</th><th>Score range</th><th>Decision</th>${compact?'':'<th>Next action</th>'}<th></th></tr></thead><tbody>${rows.map(a=>`<tr class="clickable" data-detail="${esc(a.key)}" tabindex="0" role="button" aria-label="Open ${esc(a.name||a.id||a.key)}"><td><div class="person"><div class="avatar">${esc((a.name||'?').split(/\s+/).slice(0,2).map(n=>n[0]).join(''))}</div><div><strong>${esc(a.name||'Name missing')}</strong><span class="sub">${esc(a.id||'ID missing')}</span></div></div></td><td>${esc(a.city||'City missing')}<span class="sub">${esc(a.pin||'Pin missing')}</span></td><td><span class="score">${a.grade?'<span class="grade">'+a.grade+'</span> ':''}${a.score}${a.high>a.score?'–'+a.high:''} <small>/100</small></span><span class="score-line"><i style="width:${a.score}%"></i></span></td><td>${statusTag(a)}</td>${compact?'':`<td><span class="small-text muted">${esc(nextAction(a))}</span></td>`}<td class="muted">↗</td></tr>`).join('')}</tbody></table></div>`;}
function nextAction(a){if(a.redirect)return 'Offer pin '+a.redirect.map(o=>o.pin).join(' or ')+' (suggestion only)';return {'Recommended':'Verify funding and site','Clarification needed':a.pending.length?'Confirm data corrections':a.missing.length?'Complete missing information':'Resolve conflicting information','Site needed':'Confirm site and floor','Territory review':'Resolve territory mapping','Location unavailable':'Choose another pin code','Waitlisted':'Review competing applications','Timeline review':'Agree a feasible launch date','Requirements not met':'Review funding or site size','Policy needed':'Configure brand requirements'}[a.status]||'Review application';}
const sampleButton=(cls='button')=>`<button class="${cls}" data-load-sample>Load sample data</button>`;
function decisions(){if(!results.length)return heading('DECISIONS','Every applicant, one clear decision.','Load data to see a decision, a one-line reason and the next step for each application.')+`<section class="panel"><div class="empty"><h2>No applications loaded yet</h2><p>Start with the judge-style sample (20 applications), the synthetic demo, or your own workbook.</p><div class="actions" style="justify-content:center">${sampleButton('button primary')}<button class="button" id="load-demo">Load synthetic demo</button><button class="button" data-tab="upload">${icon('upload')} Upload workbook</button></div></div></section>`;let all=[...results].sort(decSort),counts=decOrder.map(k=>[k,all.filter(a=>decKind(dec(a).label)===k).length]),list=decFilter?all.filter(a=>decKind(dec(a).label)===decFilter):all;
 const blurb={Approve:'Passes every gate and holds a slot',Conditional:'Approved once one fact is confirmed',Redirect:'Good partner, open pin suggested',Waitlist:'Qualified, no free slot or pin',Hold:'Needs data, a site or a date','Not eligible':'Below a minimum or no territory'};
 return heading('DECISIONS','Every applicant, one clear decision.','Decision, the one-line reason and the next step. Click a card to filter, or a row for the full reasoning, score and onboarding plan.',`${sampleButton()}<button class="button primary" data-tab="upload">${icon('upload')} Upload workbook</button>`)
 +`<div class="decision-cards">${counts.map(([k,n])=>`<button class="decision-card dec-${decColor[k]} ${decFilter===k?'active':''} ${n?'':'zero'}" data-decfilter="${esc(k)}" aria-pressed="${decFilter===k}"><span class="decision-card-count">${n}</span><span class="decision-card-label">${esc(k)}</span><span class="decision-card-note">${blurb[k]}</span></button>`).join('')}</div>`
 +`<section class="panel decision-panel"><div class="panel-top"><div><h2>${decFilter?esc(decFilter):'All decisions'} <span class="muted">${list.length} of ${all.length}</span></h2><div class="panel-subtitle">Source: ${esc(state.source)}</div></div>${decFilter?'<button class="text-button" data-decfilter="">Show all ×</button>':''}</div><div class="table-wrap"><table class="decision-table"><thead><tr><th>ID</th><th>Applicant</th><th>Decision</th><th>One-line reason</th><th>Next step</th></tr></thead><tbody>${list.map(a=>{let d=dec(a);return `<tr class="clickable dec-row dec-${decColor[decKind(d.label)]||'gray'}" data-detail="${esc(a.key)}" tabindex="0" role="button" aria-label="Open ${esc(a.name||a.id||a.key)}"><td data-label="ID" class="dec-id">${esc(a.id||'ID missing')}</td><td data-label="Applicant"><strong>${esc(a.name||'Name missing')}</strong><span class="sub">${esc(a.city||'City missing')} · ${esc(a.pin||'Pin missing')}</span></td><td data-label="Decision">${statusTag(a)}</td><td data-label="One-line reason" class="dec-reason">${reasonHtml(d.headline)}</td><td data-label="Next step" class="dec-next"><span class="dec-next-arrow" aria-hidden="true">→</span>${esc(d.next)}</td></tr>`;}).join('')||'<tr><td colspan="5"><div class="empty">No applicants with this decision.</div></td></tr>'}</tbody></table></div></section>`;}
function overview(){const rec=results.filter(a=>a.status==='Recommended').length,held=results.filter(a=>a.status==='Clarification needed').length,sites=results.filter(a=>a.status==='Site needed').length,slots=E.territoryCapacity(state.territories,stores).total;return heading('YOUR EXPANSION, AT A GLANCE','A clearer path to your next store.','Review the right partners. Resolve the gaps. Keep every opening moving.',`<span class="demo-tag">${state.source.startsWith('Synthetic')?'SYNTHETIC DEMO':'YOUR WORKBOOK'}</span>${sampleButton()}<button class="button primary" data-tab="upload">${icon('upload')} Upload workbook</button>`)+`<div class="stats">${[[results.length,'Total applications','Every application stays in view','applications'],[rec,'Approve or Conditional','Subject to funding and site checks','review'],[held+sites,'On hold',`${held} data clarifications · ${sites} site checks`,'assistant'],[state.territories.length,'Territories uploaded',`${rec} of ${slots} allocatable slots recommended`,'territories']].map(([n,l,d,i])=>`<div class="stat"><div class="stat-label">${l}${icon(i)}</div><div class="stat-value">${n.toString().padStart(2,'0')}</div><div class="stat-note ${i==='review'?'green':''}">${d}</div></div>`).join('')}</div>${slotsPanel()}<div class="grid-main"><section class="panel"><div class="panel-top"><div><h2>A little attention. A lot of progress.</h2><div class="panel-subtitle">The next actions that keep applications moving.</div></div><span class="tag amber">${held+sites} to review</span></div><div class="panel-body"><div class="attention-row"><div class="attention-symbol">✓</div><div><strong>Confirm proposed corrections</strong><p>${pendingCount()} values need a quick check before scoring.</p></div><button class="text-button" data-tab="review">Review →</button></div><div class="attention-row"><div class="attention-symbol">?</div><div><strong>Fill in the missing pieces</strong><p>${held} applications on Hold for incomplete or conflicting information.</p></div><button class="text-button" data-filter="Hold">View →</button></div><div class="attention-row"><div class="attention-symbol">⌖</div><div><strong>Help partners find the right space</strong><p>${sites} applications on Hold until site details are confirmed.</p></div><button class="text-button" data-filter="Hold">View →</button></div><div class="insight"><strong>Good candidates don’t disappear because a field is blank.</strong>Incomplete applications remain visible. Their score range shows what is confirmed and what could change.</div></div></section><div><section class="panel"><div class="panel-top"><h2>The expansion pipeline</h2><span class="eyebrow">LIVE</span></div><div class="panel-body">${[['Applications received',results.length],['Ready for verification',rec],['Waiting for a slot',results.filter(a=>a.status==='Waitlisted').length],['Opening checks complete',results.filter(a=>a.status==='Recommended'&&completed(a)===7).length]].map(([l,n])=>`<div class="funnel-row"><div class="funnel-head"><span>${l}</span><strong>${n}</strong></div><div class="bar"><span style="width:${results.length?n/results.length*100:0}%"></span></div></div>`).join('')}</div></section></div></div><section class="panel section-gap"><div class="panel-top"><div><h2>Partners worth a closer look</h2><div class="panel-subtitle">Approve and Conditional first, then the other decisions.</div></div><button class="text-button" data-tab="decisions">View all decisions →</button></div>${table([...results].sort(decSort).slice(0,5),true)}</section><div class="grid-main section-gap"><section class="panel"><div class="panel-top"><h2>Recent activity</h2></div><div class="panel-body">${state.audit.length?state.audit.slice(0,3).map(a=>`<div class="activity-row">${esc(a.text)}<small>${new Date(a.at).toLocaleString()}</small></div>`).join(''):'<p class="muted small-text">Corrections, application updates and onboarding progress will appear here.</p>'}</div></section><div class="callout"><div class="eyebrow">DECISIONS, EXPLAINED</div><h2>Ask what’s holding a partner back.</h2><p>Get a clear reason, or propose an update and see what changes.</p><button class="button small" data-tab="assistant">Open decision assistant ↗</button></div></div>`;}
function slotsPanel(){let rows=E.openSlots(state.territories,stores,results);if(!rows.length)return '';let by=['High','Medium','Low'].map(p=>[p,rows.filter(r=>r.priority===p).reduce((n,r)=>n+r.open,0)]),flagged=rows.filter(r=>r.flag);return `<section class="panel section-gap"><div class="panel-top"><div><h2>Open slots by priority</h2><div class="panel-subtitle">Fill High-priority territories first. ${by.map(([p,n])=>`${p}: ${n} open`).join(' · ')}</div></div>${flagged.length?`<span class="tag red">${flagged.length} High territor${flagged.length>1?'ies':'y'} unfilled</span>`:'<span class="tag green">High territories filled</span>'}</div>${flagged.length?`<div class="info-row warning">High priority with unfilled slots: ${flagged.map(r=>`${esc(r.id)} ${esc(r.city)} (${r.open} of ${r.available} open)`).join('; ')}.</div>`:''}<div class="table-wrap"><table><thead><tr><th>Territory</th><th>City</th><th>Priority</th><th>Allocatable</th><th>Recommended</th><th>Open</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.id)}${r.issues.length?'<span class="sub">Excluded: '+esc(r.issues.join(', '))+'</span>':''}</td><td>${esc(r.city)}</td><td><span class="tag ${r.priority==='High'?'green':r.priority==='Medium'?'amber':'gray'}">${esc(r.priority)}</span></td><td>${r.available}</td><td>${r.recommended}</td><td><strong>${r.open}</strong>${r.flag?' <span class="tag red">Fill first</span>':''}</td></tr>`).join('')}</tbody></table></div></section>`;}
function applications(){let list=results.filter(a=>(!filter||dec(a).label===filter||decKind(dec(a).label)===filter)&&(!query||[a.id,a.name,a.city,a.pin].some(v=>String(v||'').toLowerCase().includes(query.toLowerCase())))).sort((a,b)=>b.score-a.score);return heading('PARTNER PIPELINE','Every application, accounted for.','Scores help you prioritise. The decision tells you what can happen next.',`<button class="button primary" data-tab="upload">Upload workbook</button>`)+`<section class="panel"><div class="panel-top"><div><h2>Applications <span class="muted">${list.length}</span></h2><div class="panel-subtitle">Recorded-input score to possible score · click a partner to see the reasoning.</div></div></div><div class="table-toolbar"><input id="search" class="input search" placeholder="Search name, ID, city or pin…" value="${esc(query)}" aria-label="Search applications"><select id="status-filter" class="input" aria-label="Filter by decision"><option value="">All decisions</option>${(()=>{let labs=[...new Set([...results].sort(decSort).map(a=>dec(a).label))],opts=[];for(let k of decOrder){let sub=labs.filter(l=>decKind(l)===k);if(!sub.length)continue;if(k==='Hold')opts.push(['Hold','Hold (all)'],...sub.map(l=>[l,'· '+l]));else opts.push([k,k]);}if(filter&&!opts.some(o=>o[0]===filter))opts.push([filter,filter]);return opts.map(([v,t])=>`<option value="${esc(v)}" ${v===filter?'selected':''}>${esc(t)}</option>`).join('');})()}</select></div><div id="app-table">${table(list)}</div></section><p class="hint">Tie-breaks: confirmed score, sooner stated launch, then application ID. Unknown score components never inflate the confirmed score.</p>`;}
function review(){let cards=[];for(let a of state.apps)for(let [i,p] of a.pending.entries())cards.push(`<div class="review-card"><div class="actions" style="justify-content:space-between"><div><strong>${esc(a.name||a.id||a.key)}</strong> <span class="sub">${esc(a.id)} · ${esc(E.labels[p.field])}</span></div><button class="text-button" data-detail="${esc(a.key)}">Open application ↗</button></div><div class="review-values"><div><small>ORIGINAL VALUE</small>${esc(p.raw)}</div><span class="muted">→</span><div><small>PROPOSED VALUE · ${esc(p.reason||E.labels[p.field])}</small><input class="input" id="correction-${esc(a.key)}-${i}" type="number" min="0" step="any" value="${esc(p.proposed??'')}" placeholder="Enter a confirmed number" aria-label="Confirmed ${esc(E.labels[p.field])}"></div></div><button class="button primary small" data-confirm-correction="${esc(a.key)}" data-index="${i}">Confirm correction</button> <button class="button small" data-reject-correction="${esc(a.key)}" data-index="${i}">Mark as missing</button></div>`);return heading('DATA QUALITY','Clean data. With your confirmation.','Original answers are preserved. Proposed changes take effect only when confirmed.')+`<section class="panel"><div class="panel-top"><h2>Proposed corrections</h2><span class="tag amber">${cards.length} awaiting confirmation</span></div>${cards.join('')||'<div class="empty"><h2>No corrections waiting</h2>Missing or contradictory information can still need review.</div>'}</section><section class="panel section-gap"><div class="panel-top"><h2>Applications needing clarification</h2></div>${table(results.filter(a=>a.status==='Clarification needed'),true)}</section>${state.warnings.length?`<div class="info-row warning">${state.warnings.map(esc).join('<br>')}</div>`:''}`;}
function territories(){return heading('GEO-SELECTION','Make room for the right partner.','One store per pin code. Recommendations always respect territory capacity.')+`<div class="territory-grid">${state.territories.map(t=>{let rec=results.filter(a=>a.territory===t.id&&a.status==='Recommended'),app=results.filter(a=>a.territory===t.id);return `<section class="panel territory-card"><div class="actions" style="justify-content:space-between"><span class="eyebrow">${esc(t.id)}</span><span class="tag ${t.priority==='High'?'green':t.priority==='Medium'?'amber':'gray'}">${esc(t.priority||'Unknown')} priority</span></div><div class="city-name">${esc(t.city)}</div><div class="small-text muted">${esc(t.tier)} · ${esc(t.state)}</div><div class="pin-list">${esc(t.pins.join(' · '))}</div>${t.issues?.length?`<div class="info-row warning">${t.issues.map(esc).join('<br>')}</div>`:''}<div class="territory-meta"><div>Applications<strong>${app.length}</strong></div><div>Recommended<strong>${rec.length}<span class="muted" style="font-size:12px"> / ${esc(t.slots??'?')}</span></strong></div></div><div class="compact">${rec.map(a=>`<button class="text-button" data-detail="${esc(a.key)}">${esc(a.name)} ↗</button><br>`).join('')||'<span class="hint">No partners recommended yet</span>'}</div></section>`;}).join('')||'<div class="empty">Upload territories to map your expansion.</div>'}</div><section class="panel section-gap"><div class="panel-top"><div><h2>Existing store footprint</h2><div class="panel-subtitle">Fixed brand list from the case · these 10 pin codes are unavailable.</div></div></div><div class="table-wrap"><table><thead><tr><th>Store</th><th>City</th><th>Pin code</th><th>Opened</th></tr></thead><tbody>${stores.map(s=>`<tr><td>${s.id}</td><td>${s.city}</td><td>${s.pin}</td><td>${s.year}</td></tr>`).join('')}</tbody></table></div></section>`;}
function completed(a){return Object.values(state.tasks[a.key]||{}).filter(Boolean).length;}
function onboarding(){let order=E.onboardingOrder(results,state.territories),list=[...order,...results.filter(a=>a.status!=='Recommended'&&completed(a)>0)];return heading('OPENING READINESS','From a good fit to an open store.','Launch sequence: High-priority territories first, then Medium, then Low. Within a priority, sooner target launch goes first.')+`<section class="panel"><div class="panel-top"><h2>Partner onboarding</h2><span class="tag green">${list.length} partners</span></div>${list.map(a=>`<div class="onboarding-summary"><div><strong>${esc(a.name)}</strong><span class="sub">${order.includes(a)?'#'+(order.indexOf(a)+1)+' · ':''}${esc(a.id)} · ${esc(a.city)} · ${esc(state.territories.find(t=>t.id===a.territory)?.priority||'Unknown')} priority · Training: ${esc(a.language||'Confirm language')}</span><div class="compact">${statusTag(a)}</div></div><div><span class="small-text muted">${completed(a)} of 7 steps complete</span><div class="bar compact"><span style="width:${completed(a)/7*100}%"></span></div></div><button class="button small" data-detail="${esc(a.key)}">Open checklist ↗</button></div>`).join('')||'<div class="empty"><h2>Your next opening starts here</h2>Approved and Conditional partners will appear with their verification and training plan.</div>'}</section><div class="info-row">Recommendations are provisional. Funding, site suitability and signed agreements are verified in the checklist. Training completion is recorded by the operator; this MVP does not provide a learning-management system.</div>`;}
function assistant(){let pick=fn=>results.find(a=>a.id&&fn(a))?.id,hold=pick(a=>/^Hold/.test(dec(a).label))||pick(()=>true)||'APP-007',fwd=pick(a=>a.status==='Recommended')||hold,moved=pick(a=>a.redirect)||pick(a=>a.status==='Location unavailable')||hold,site=pick(a=>a.space==='Not yet identified')||hold,city=results.find(a=>a.city)?.city||'Bengaluru';let prompts=[`Why is ${hold} on hold?`,`What should ${fwd} do next?`,`How will ${fwd} be trained?`,`Can ${moved} open somewhere else?`,'Which territory should we fill first?',`Is there cannibalisation risk for ${moved}?`,`Who are the top applicants in ${city}?`,`${site} has now found a ground-floor space`];let selected=results.find(a=>a.key===botContext);return heading('RIGHT PIN BOT','Understand the decision. Ask the next question.','Get reasons, request clarification, compare applicants or preview a change.')+`<div class="chat-layout"><section class="panel"><div class="panel-top"><div><h2>Ask Right Pin</h2><div class="panel-subtitle">${selected?'Talking about '+esc(selected.id)+' · follow-up questions can omit the ID':'Answers grounded in your current workbook'}</div></div><button class="text-button" id="clear-chat">New conversation</button></div><div class="chat-log" id="chat-log" role="log" aria-live="polite">${(chat.length?chat:[{text:'I can explain decisions, scoring and assumptions; compare partners; and draft clarification questions. Ask a what-if question to preview a change, or state an update to review before confirming.\n\nI use the workbook and the visible assessment policy. I will ask when a fact is ambiguous.',user:false}]).map(m=>`<div class="message ${m.user?'user':''}"><span class="message-author">${m.user?'You':'Right Pin'}</span>${esc(m.text)}</div>`).join('')}${pendingChat?`<div class="message proposal"><strong>Confirm proposed update</strong><br>${esc(pendingChat.id)}<br>${pendingChat.followUp?.length?'<span class="hint">Answer the question above to add the missing details, or confirm what is known so far.</span><br>':''}${Object.entries(pendingChat.patch).map(([f,v])=>`${esc(E.labels[f])}: ${esc(state.apps.find(a=>a.key===pendingChat.key)?.[f]??'Missing')} → ${esc(v)}`).join('<br>')}<div class="actions compact">${Object.keys(pendingChat.patch).length?'<button class="button primary small" id="confirm-chat">Confirm & reassess</button>':''}<button class="button small" id="cancel-chat">Cancel</button></div></div>`:''}</div><form class="chat-input" id="chat-form"><input class="input" id="chat-text" placeholder="Ask why, compare partners, or describe an update…" aria-label="Message to decision assistant" required maxlength="3000"><button class="button primary">Send ↗</button></form></section><aside><section class="panel"><div class="panel-top"><h2>Try asking</h2></div><div class="panel-body">${prompts.map(p=>`<button class="prompt" data-prompt="${esc(p)}">${esc(p)} ↗</button>`).join('')}<p class="hint">Evidence-based, rules-driven replies. No external AI model or outside market data. Unclear facts are left for confirmation.</p></div></section></aside></div>`;}
// Illustrative starting points per retail format. Not real brand requirements; every value stays editable.
const presets={eyewear:{label:'Eyewear store (current default)',minInvestment:30,minArea:400,minLaunch:3,targetLaunch:6},apparel:{label:'Apparel store',minInvestment:40,minArea:800,minLaunch:3,targetLaunch:6},electronics:{label:'Mobile and electronics',minInvestment:25,minArea:300,minLaunch:2,targetLaunch:4},pharmacy:{label:'Pharmacy',minInvestment:20,minArea:250,minLaunch:2,targetLaunch:4},qsr:{label:'Quick-service restaurant',minInvestment:45,minArea:600,minLaunch:4,targetLaunch:8},delivery:{label:'Last-mile delivery hub',minInvestment:15,minArea:1000,minLaunch:1,targetLaunch:3}};
let lastRuleChange=null;
function ruleInput(name,value,placeholder,attrs=''){return `<input class="input" name="${name}" type="number" min="0" step="any" value="${esc(value??'')}" placeholder="${esc(placeholder??'')}" ${attrs}>`;}
function rulesEditor(){let st=state.settings,w=E.weightsOf(st),tiers=st.tiers||{},citiesRules=st.cities||{},floors=st.acceptFloors||[];
 let geoRow=(group,key,sub)=>{let o=(group==='tier'?tiers:citiesRules)[key]||{},base=group==='city'?(tiers[E.cities[key][1]]||{}):{};return `<tr><td><strong>${esc(key)}</strong>${sub?`<span class="sub">${esc(sub)}</span>`:''}</td><td>${ruleInput(`${group}|${key}|minInvestment`,o.minInvestment,base.minInvestment||st.minInvestment)}</td><td>${ruleInput(`${group}|${key}|minArea`,o.minArea,base.minArea||st.minArea)}</td></tr>`;};
 return `<section class="panel rules-editor"><div class="panel-top"><div><h2>Decision rules</h2><div class="panel-subtitle">Edit any rule and save: every application is rescored by the same engine and the changes are listed.</div></div><span class="tag amber">Proposed pilot assumptions</span></div><form id="settings-form" class="panel-body">
 <div class="rules-block"><h3>1. Start from an industry preset</h3><div class="rules-row"><select id="preset" name="preset" class="input" aria-label="Industry preset"><option value="">Custom (keep my values)</option>${Object.entries(presets).map(([k,p])=>`<option value="${k}" ${st.preset===k?'selected':''}>${esc(p.label)}</option>`).join('')}</select><p class="hint">Illustrative starting values for each retail format, not published brand requirements. Choosing one fills the base rule below; nothing changes until you save.</p></div></div>
 <div class="rules-block"><h3>2. Base rule</h3><div class="rules-grid"><label>Minimum investment incl. reserve (₹ lakh)${ruleInput('minInvestment',st.minInvestment,'','required min="0.01"')}</label><label>Minimum usable area (sq ft)${ruleInput('minArea',st.minArea,'','required min="1"')}</label><label>Minimum feasible launch (months)${ruleInput('minLaunch',st.minLaunch,'','required min="0.1"')}</label><label>Target latest launch (months)${ruleInput('targetLaunch',st.targetLaunch,'','required min="0.1"')}</label></div></div>
 <div class="rules-block"><h3>3. Geography rules</h3><p class="hint">Leave blank to inherit. A city rule beats its tier rule, which beats the base rule. Reasons name the rule that applied, for example "required for Bengaluru".</p><div class="table-wrap"><table class="rules-table"><thead><tr><th>Applies to</th><th>Min investment (₹ lakh)</th><th>Min area (sq ft)</th></tr></thead><tbody>${['Tier 1','Tier 2','Tier 3'].map(t=>geoRow('tier',t,Object.keys(E.cities).filter(c=>E.cities[c][1]===t).join(', '))).join('')}${Object.keys(E.cities).map(c=>geoRow('city',c,E.cities[c][1])).join('')}</tbody></table></div></div>
 <div class="rules-block"><h3>4. Score weights</h3><div class="rules-grid">${[['funds','Declared funds'],['premises','Premises readiness'],['operator','Operator experience'],['launch','Feasible launch']].map(([k,l])=>`<label>${l} (%)${ruleInput('weight|'+k,w[k],'','required data-weight')}</label>`).join('')}</div><p class="hint" id="weight-sum">Total: ${Object.values(w).reduce((a,b)=>a+b,0)} of 100</p></div>
 <div class="rules-block"><h3>5. Floor rule</h3><p class="hint">Ground and First always count as a confirmed floor. Tick a value to accept it too; otherwise those applicants stay on Hold until the actual floor is confirmed.</p>${E.optionalFloors.map(fl=>`<label class="check-line"><input type="checkbox" name="floor|${fl}" ${floors.includes(fl)?'checked':''}> Accept "${fl}" as a confirmed floor</label>`).join('')}</div>
 <div class="actions"><button class="button primary">Save & rescore</button><button type="button" class="button" id="reset-rules">Reset to defaults</button></div>
 ${lastRuleChange?`<div class="info-row"><strong>Last save: ${lastRuleChange.length} decision${lastRuleChange.length===1?'':'s'} changed.</strong>${lastRuleChange.slice(0,12).map(c=>`<br>${esc(c.id)}: ${esc(c.before)} → ${esc(c.after)}`).join('')}${lastRuleChange.length>12?'<br>See History for the rest.':''}</div>`:''}</form></section>`;}
function readRules(form){let fd=new FormData(form),out={model:'industry-v2',preset:fd.get('preset')||''},tiers={},citiesRules={},weights={},acceptFloors=[];
 for(let k of ['minInvestment','minArea','minLaunch','targetLaunch'])out[k]=Number(fd.get(k));
 for(let [k,v] of fd.entries()){let p=k.split('|');if(p[0]==='tier'||p[0]==='city'){if(v!==''){let g=p[0]==='tier'?tiers:citiesRules;(g[p[1]]??={})[p[2]]=Number(v);}}else if(p[0]==='weight')weights[p[1]]=Number(v);else if(p[0]==='floor')acceptFloors.push(p[1]);}
 return {...out,tiers,cities:citiesRules,weights,acceptFloors};}
function applyRules(candidate){let errors=E.policyErrors(candidate);if(errors.length){toast(errors.join(' '));return false;}let before=results.map(r=>({key:r.key,id:r.id||r.key,label:dec(r).label}));pendingChat=null;state.settings=candidate;calculate();lastRuleChange=results.map(r=>({id:r.id||r.key,before:before.find(b=>b.key===r.key)?.label,after:dec(r).label})).filter(c=>c.before&&c.before!==c.after);audit(`Updated decision rules and reassessed all applications. ${lastRuleChange.length} decision${lastRuleChange.length===1?'':'s'} changed.`);save();render();toast(`Rules saved. ${lastRuleChange.length} decision${lastRuleChange.length===1?'':'s'} changed.`);return true;}
function rules(){return heading('RESEARCH AND ASSESSMENT','Requirements first. Evidence before approval.','Edit the decision rules below. A proposed screening policy informed by published franchise-selection practice.')+rulesEditor()+`<div class="settings-grid"><section class="panel"><div class="panel-top"><h2>Screening fit score</h2><span class="tag green">Version 2</span></div><div class="panel-body">${[['Declared financial adequacy',35,'35 × min(declared investment / configured requirement, 1)'],['Premises readiness',30,'Identified owned or rented site 15; area adequacy up to 15'],['Operator experience',25,'Retail experience up to 20; explicit previous business operation 5'],['Feasible launch plan',10,'Inside the configured window 10; later 5; too soon 0 and review']].map(([s,n,d])=>`<div class="weight-row"><strong>${s}</strong><strong>${n}%</strong></div><div class="bar"><span style="width:${n}%;background:#2c7359"></span></div><p class="hint">${d}</p>`).join('')}<p class="small-text muted">Retail experience anchors: 0 years = 0 points; under 1 year = 5; 1–under 3 years = 10; 3–under 5 years = 15; 5+ years = 20. These anchors and weights are proposed pilot choices.</p><div class="info-row">Owned and rented premises receive equal points. Funding and area stop earning additional points once the requirement is met. Floor must be clarified and assessed, with no generic ground-floor bonus.</div><p class="small-text muted">Proposed grades: A 80–100; B 65–below 80; C 50–below 65; D below 50. U means one or more scored inputs remain unknown. A grade never overrides a failed requirement or a location restriction.</p></div></section><section class="panel"><div class="panel-top"><h2>Illustrative retail profile</h2><span class="tag amber">Replace with brand policy</span></div><div class="panel-body"><p class="small-text muted">₹30 lakh, 400 sq ft and 3–6 months are demonstration assumptions for this unnamed brand. They are not Lenskart requirements or universal industry thresholds. Required investment should include setup costs and an explicit working-capital reserve agreed with the brand.</p><p class="small-text muted">Edit these values in Decision rules at the top of this page.</p></div></section><section class="panel"><div class="panel-top"><h2>What the research establishes</h2></div><div class="panel-body"><p class="small-text muted">The reviewed sources support brand-specific financial capacity, site suitability, operator capability, due diligence and training. They do not establish one universal numerical grade. The score above is our proposed screening implementation; approval still requires a verified business case and human review.</p><p class="small-text"><a href="franchise-methodology.docx" download>Download research and methodology document ↓</a></p><ul class="help-list"><li><a href="https://www.bdc.ca/en/articles-tools/business-strategy-planning/manage-growth/how-select-potential-franchisees" target="_blank" rel="noopener">BDC and Canadian Franchise Association guidance</a></li><li><a href="https://www.wipo.int/edocs/pubdocs/en/sme/1035/wipo_pub_1035.pdf" target="_blank" rel="noopener">WIPO guide to franchising</a></li><li><a href="https://www.ftc.gov/business-guidance/resources/consumers-guide-buying-franchise" target="_blank" rel="noopener">FTC due-diligence guidance, United States</a></li><li><a href="https://journals.sagepub.com/doi/10.1177/097226290901300104" target="_blank" rel="noopener">Saraogi 2009: research in the Indian context</a></li><li><a href="https://partners.lenskart.com/" target="_blank" rel="noopener">Lenskart official partner form: owned or rented</a></li></ul><p class="hint">International guidance is used for process design, not represented as Indian law. Published brand criteria vary by format and territory.</p></div></section><section class="panel"><div class="panel-top"><h2>Evidence and eligibility</h2></div><div class="panel-body"><ul class="help-list"><li>Missing or contradictory data stays in the pipeline for clarification.</li><li>Declared investment below the configured requirement is a hold.</li><li>Area below the configured minimum and infeasible launch timing cannot be offset by experience.</li><li>Existing-store pins, one store per pin and territory slots remain mandatory.</li><li>Territory priority rule (proposed pilot assumption): High-priority territories are filled, onboarded and launched first, then Medium, then Low. Redirect suggestions offer High-priority pins first. Priority never changes who wins inside a territory; that is decided by score.</li><li>Before an offer, verify funds, funding conditions, working capital, site rights, demand, rent economics and operator fit.</li><li>Financial statements, signed leases, interviews and actual catchment evidence are absent from the uploaded template. They are not inferred.</li></ul><p class="small-text muted">Version 2 uses absolute requirements, so adding an unrelated applicant never changes an existing score.</p></div></section></div>`;}
function upload(){return heading('IMPORT APPLICATIONS','Bring your next opportunities in.','Upload the original test format. Incomplete records are welcome.',`<a class="button" href="template.xlsx" download>Download template ↓</a>`)+`<section class="panel"><div class="panel-top"><div><h2>Upload an Excel workbook</h2><div class="panel-subtitle">Applications and Territories · fixed existing-store list stays protected.</div></div><span class="tag gray">.xlsx · up to 10 MB</span></div><div class="panel-body"><div class="dropzone" id="dropzone" tabindex="0" role="button" aria-label="Choose XLSX workbook"><div class="drop-icon">${icon('upload')}</div><h2>Drop your workbook here</h2><p>or click to choose a file from your computer.<br>Your file is processed in your browser.</p><span class="button primary">Choose workbook</span></div><label class="check-line"><input type="checkbox" id="include-examples"> Include row 3 examples from the supplied template</label><p class="hint">The template says row 3 is an example and real entries begin at row 4. Turn this on to test the template’s sample application and territory.</p><div id="import-preview"></div><p class="small-text"><a href="qa-test-data.xlsx" download>Download synthetic stress-test workbook ↓</a> · <a href="qa-rescoring.csv" download>Download initial rescoring results ↓</a></p><div class="info-row">Each import replaces this browser’s current workspace after confirmation. Export a backup first if you want to keep your current work.</div><div class="actions">${sampleButton('button primary')}<button class="button" id="load-demo">Load synthetic demo</button><button class="button" id="restore">Restore workspace backup</button></div></div></section>`;}
function modal(content){$('#overlay').innerHTML=`<section class="drawer" role="dialog" aria-modal="true" aria-label="Application workspace">${content}</section>`;$('#overlay').hidden=false;document.body.style.overflow='hidden';$('#overlay').querySelector('button,input,select')?.focus();}
function close(){ $('#overlay').hidden=true;$('#overlay').innerHTML='';document.body.style.overflow='';}
function planFor(a){return E.onboardingPlan(a,{today:new Date(),stores,settings:state.settings});}
function planBlock(a,plan){return `<div class="plan-head"><div><span class="hint">Target launch</span><strong>${plan.launchMonths} months${plan.assumedLaunch?' (assumed)':''} · ${esc(plan.launchDate)}</strong></div><div><span class="hint">Planned opening</span><strong>Week ${plan.openWeek} · ${esc(plan.openDate)}</strong></div></div>${plan.flags.map(f=>`<div class="info-row warning">${esc(f)}</div>`).join('')}<div class="timeline">${plan.steps.map(s=>`<div class="timeline-row"><span class="timeline-week">Wk ${s.start}${s.end>s.start?'–'+s.end:''}</span><span class="timeline-bar"><i style="margin-left:${(s.start-1)/Math.max(plan.openWeek,plan.weeks)*100}%;width:${s.len/Math.max(plan.openWeek,plan.weeks)*100}%"></i></span><span><strong>${esc(s.title)}</strong> <span class="sub">${esc(s.owner)} · ${esc(s.from)} to ${esc(s.to)}</span></span></div>`).join('')}</div><div class="info-row"><strong>Training plan.</strong> ${esc(plan.training.text)}</div><div class="needed"><strong>Still needed from the partner</strong><ul class="help-list">${plan.needed.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></div>`;}
function detail(key){let a=results.find(a=>a.key===key);if(!a)return;let tasks=state.tasks[key]||{},dates=state.taskDates[key]||{},plan=planFor(a);modal(`<div class="drawer-head"><div><span class="eyebrow">${esc(a.id||'ID missing')} · ${esc(a.city||'City missing')}</span><h2>${esc(a.name||'Name missing')}</h2>${statusTag(a)}<span class="sub">Internal status: ${esc(a.status)}</span></div><button class="close" data-close aria-label="Close dialog">×</button></div><div class="detail-score"><div><div class="eyebrow">RECORDED INPUTS TO POSSIBLE SCORE</div><div class="big-score">${a.score}${a.high>a.score?'–'+a.high:''}<small> /100</small></div></div><div><div class="small-text">${a.high>a.score?'Some components remain unknown':'All components scored'}</div><small>Grade ${esc(a.grade)} · proposed screening band</small></div></div><section class="panel"><div class="panel-top"><h2>Why this decision?</h2><button class="button small" data-ask-bot="${esc(key)}">Ask bot ↗</button></div><div class="panel-body"><div class="reason"><strong>${esc(dec(a).headline)}</strong></div>${a.reasons.filter(r=>r!==dec(a).headline).map(r=>`<div class="reason">${esc(r)}</div>`).join('')}<div class="info-row"><strong>Next step:</strong> ${esc(dec(a).next)}</div></div></section><section class="panel"><div class="panel-top"><h2>Score breakdown</h2></div><div class="table-wrap"><table class="breakdown"><thead><tr><th>Component</th><th>Points</th><th>Contribution</th></tr></thead><tbody>${a.components.map(c=>`<tr><td>${esc(c.label)}<span class="sub">${esc(c.detail)}</span></td><td>${c.points===null?'Unknown':c.points+' / '+c.max}</td><td>${c.points===null?'0–'+c.weight:c.contribution.toFixed(1)} / ${c.weight}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-top"><h2>Application details</h2><button class="button small" data-edit="${esc(key)}">Edit application</button></div><div class="panel-body"><div class="form-grid">${E.fields.filter(f=>!['name','id'].includes(f)).map(f=>`<div><span class="hint">${esc(E.labels[f])}</span><div class="small-text">${esc(a[f]??'Missing')}</div></div>`).join('')}</div></div></section><section class="panel"><div class="panel-top"><h2>Onboarding plan</h2><span class="tag gray">${completed(a)} / 7</span></div><div class="panel-body">${planBlock(a,plan)}${a.status!=='Recommended'?'<div class="info-row warning">Onboarding is paused until the decision is Approve or Conditional. Resolve its current next action first.</div>':''}${taskDefs.map(([title,desc,owner],i)=>`<div class="task-row ${tasks[i]?'done':''}"><input type="checkbox" data-task="${esc(key)}" data-task-index="${i}" ${tasks[i]?'checked':''} ${a.status!=='Recommended'||(i>0&&!tasks[i-1])||(i===5&&!a.language)?'disabled':''} aria-label="Complete ${title}"><div style="flex:1"><strong>${i+1}. ${title}</strong> <span class="tag gray">Week ${plan.steps[i].start}${plan.steps[i].end>plan.steps[i].start?'–'+plan.steps[i].end:''} · ${esc(plan.steps[i].from)}</span><p>${desc}</p><label class="hint">Due date <input class="input" style="font-size:10px;min-height:26px;padding:4px" type="date" data-task-date="${esc(key)}" data-task-index="${i}" value="${esc(dates[i]||'')}" aria-label="Due date for ${title}"></label></div></div>`).join('')}</div></section><details class="small-text muted"><summary>Original imported values</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(JSON.stringify(a.raw,null,2))}</pre></details>`);}
function edit(key){let a=state.apps.find(a=>a.key===key);if(!a)return;let choices={city:Object.keys(E.cities),state:['Karnataka'],space:['Owned','Rented','Not yet identified'],floor:['Ground','Upper','Mall unit','Not known','First','Other confirmed'],language:['Kannada','English','Hindi']};modal(`<div class="drawer-head"><div><div class="eyebrow">CONFIRM AN UPDATE</div><h2>Edit ${esc(a.id||'application')}</h2></div><button class="close" data-close aria-label="Close dialog">×</button></div><p class="small-text muted">Changes update the assessment and territory allocation. Original imported values are retained.</p><form id="edit-form" data-key="${esc(key)}"><div class="form-grid">${E.fields.map(f=>`<label class="${f==='notes'||f==='business'?'full':''}">${esc(E.labels[f])}${choices[f]?`<select class="input" name="${f}"><option value="">Missing / unconfirmed</option>${choices[f].map(c=>`<option value="${esc(c)}" ${a[f]===c?'selected':''}>${esc(c)}</option>`).join('')}</select>`:f==='notes'||f==='business'?`<textarea class="input" name="${f}">${esc(a[f])}</textarea>`:`<input class="input" name="${f}" ${E.numeric.includes(f)?'type="number" min="0" step="any"':''} value="${esc(a[f])}" ${f==='pin'?'inputmode="numeric" maxlength="6"':''}>`}</label>`).join('')}</div><div class="actions section-gap"><button class="button primary">Confirm changes & reassess</button><button type="button" class="button" data-detail="${esc(key)}">Cancel</button></div></form>`);}
function applyPatch(key,patch,why){let a=state.apps.find(a=>a.key===key);if(!a)return;let before=results.find(x=>x.key===key);pendingChat=null;let changed=Object.fromEntries(Object.entries(patch).filter(([k,v])=>a[k]!==v));state.tasks[key]=E.invalidateTasks(state.tasks[key]||{},changed);Object.assign(a,patch);a.pending=a.pending.filter(p=>!(p.field in patch));calculate();let after=results.find(x=>x.key===key);audit(`${a.id||a.key}: ${why}. ${before?.status} → ${after.status}; score ${before?.score} → ${after.score}.`);save();render();return {before,after};}
function explanation(a){return `${a.id} · ${a.name||'Name missing'}\n${a.status} · Score ${a.score}${a.high>a.score?'–'+a.high:''}/100\n\n${a.reasons.join('\n')}\n\nNext action: ${nextAction(a)}.\n\n${a.components.map(c=>`${c.label}: ${c.points===null?'unknown':c.points+'/'+c.max+' points'} (${c.points===null?'0–'+c.weight:c.contribution.toFixed(1)} of ${c.weight})`).join('\n')}`;}
function send(text){if(!text.trim())return;chat.push({text,user:true});let pending=pendingChat;pendingChat=null;let response=FranchiseBot.answer(text,{state,results,stores,contextKey:botContext,pending});botContext=response.contextKey||null;chat.push({text:response.text});pendingChat=response.proposal||null;chat=chat.slice(-100);save();render();$('#chat-log').scrollTop=$('#chat-log').scrollHeight;}
function download(name,text,type){let blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportModal(){modal(`<div class="drawer-head"><h2>Save your results</h2><button class="close" data-close aria-label="Close dialog">×</button></div><p class="small-text muted">This workspace is stored in this browser. Use a backup to continue on another device.</p><div class="actions"><button class="button primary" id="export-csv">Download assessment CSV</button><button class="button" id="export-json">Download workspace backup</button><button class="button" id="restore">Restore a backup</button></div><div class="info-row">CSV includes decisions and next actions. JSON preserves applications, corrections, rules, frozen benchmarks, tasks and activity.</div>`);}
async function parseFile(file){if(!file)return;importPreview=null;if($('#import-preview'))$('#import-preview').innerHTML='';try{toast('Reading workbook…');let sheets=await WorkbookReader.readWorkbook(file),include=$('#include-examples')?.checked||false;let parsed=WorkbookReader.importRows(sheets,include,stores);importPreview={...parsed,source:file.name};$('#import-preview').innerHTML=`<div class="info-row"><strong>${esc(file.name)}</strong><br>${parsed.apps.length} applications · ${parsed.territories.length} territories · ${parsed.apps.reduce((n,a)=>n+a.pending.length,0)} proposed corrections</div>${parsed.warnings.length?`<div class="info-row warning">${parsed.warnings.map(esc).join('<br>')}</div>`:''}<button id="confirm-import" class="button primary" ${!parsed.apps.length?'disabled':''}>Replace workspace & import</button>`;toast('Workbook read. Review the summary before importing.');}catch(e){toast(e.message||'The workbook could not be read.');}$('#file').value='';}
async function loadDemo(initial=false){try{let data=await(await fetch('demo.json')).json();pendingChat=null;chat=[];botContext=null;state={apps:data.apps.map((a,i)=>E.normalize(a,'demo-'+i)),territories:data.territories,reference:null,settings:{...E.defaultPolicy},tasks:{},taskDates:{},audit:[],source:'Synthetic demo · 24 applicants',warnings:[]};state.reference=E.benchmarks(state.apps);audit('Loaded synthetic demo data. These are fictional applicants.');save();tab=(initial&&location.hash.slice(1))||'decisions';location.hash=tab;render();if(!initial)toast('Synthetic demo loaded.');}catch(e){toast('Could not load demo. Upload a workbook to get started.');render();}}
function replaceWorkspace(p){pendingChat=null;chat=[];botContext=null;state={apps:p.apps,territories:p.territories,reference:E.benchmarks(p.apps),settings:{...E.defaultPolicy},tasks:{},taskDates:{},audit:[],source:p.source,warnings:p.warnings};audit(`Imported ${p.apps.length} applications and ${p.territories.length} territories from ${p.source}.`);save();importPreview=null;tab='decisions';location.hash=tab;filter='';query='';render();}
async function loadSample(){if(!confirm('Replace this browser’s workspace with the judge-style sample (20 applications)? Export a backup first if needed.'))return;try{toast('Loading sample data…');let r=await fetch('sample-judge-test.xlsx').catch(()=>null);if(!r||!r.ok)throw Error('Sample data is not available yet (sample-judge-test.xlsx not found). Upload a workbook or load the synthetic demo.');let file=new File([await r.blob()],'sample-judge-test.xlsx'),sheets=await WorkbookReader.readWorkbook(file),p=WorkbookReader.importRows(sheets,false,stores);if(!p.apps.length)throw Error('The sample workbook has no applications.');replaceWorkspace({...p,source:'sample-judge-test.xlsx (judge-style sample, 20 applications)'});toast('Sample data loaded. Every application has a decision below.');}catch(e){toast(e.message||'Sample data could not be loaded. Upload a workbook or load the synthetic demo.');}}
function bindPage(){if($('#search'))$('#search').oninput=e=>{query=e.target.value;let pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};if($('#status-filter'))$('#status-filter').onchange=e=>{filter=e.target.value;render();};if($('#chat-form'))$('#chat-form').onsubmit=e=>{e.preventDefault();send($('#chat-text').value);};if($('#settings-form')){let form=$('#settings-form'),sum=()=>{let t=[...form.querySelectorAll('[data-weight]')].reduce((a,x)=>a+(Number(x.value)||0),0);$('#weight-sum').textContent=`Total: ${+t.toFixed(2)} of 100`;$('#weight-sum').classList.toggle('bad',Math.abs(t-100)>0.01);};form.querySelectorAll('[data-weight]').forEach(x=>x.oninput=sum);$('#preset').onchange=e=>{let p=presets[e.target.value];if(!p)return;for(let k of ['minInvestment','minArea','minLaunch','targetLaunch'])form.elements[k].value=p[k];toast(`${p.label} values filled in. Save to rescore.`);};form.onsubmit=e=>{e.preventDefault();applyRules(readRules(form));};$('#reset-rules').onclick=()=>{if(confirm('Reset every decision rule to the default pilot assumptions?'))applyRules({...E.defaultPolicy});};}if($('#dropzone')){let d=$('#dropzone');d.onclick=()=>$('#file').click();d.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#file').click();}};d.ondragover=e=>{e.preventDefault();d.classList.add('drag');};d.ondragleave=()=>d.classList.remove('drag');d.ondrop=e=>{e.preventDefault();d.classList.remove('drag');parseFile(e.dataTransfer.files[0]);};}}
document.addEventListener('click',e=>{let el=e.target.closest('button,a,tr[data-detail]');if(!el)return;let d=el.dataset;if(d.decfilter!==undefined){decFilter=decFilter===d.decfilter?'':d.decfilter;render();return;}if(d.askBot){close();botContext=d.askBot;tab='assistant';location.hash=tab;render();let a=results.find(a=>a.key===botContext);send('Why is '+a.id+' '+E.decision(a).label+'?');}else if(d.tab){tab=d.tab;location.hash=tab;render();}else if(d.filter){filter=d.filter;query='';tab='applications';location.hash=tab;render();}else if(d.detail)detail(d.detail);else if(d.edit)edit(d.edit);else if('close'in d)close();else if(d.prompt)send(d.prompt);else if(el.id==='clear-chat'){pendingChat=null;chat=[];botContext=null;save();render();}else if(d.confirmCorrection){let a=state.apps.find(a=>a.key===d.confirmCorrection),p=a.pending[Number(d.index)],v=document.getElementById('correction-'+a.key+'-'+d.index).value;if(v===''||!Number.isFinite(Number(v))||Number(v)<0){toast('Enter a valid non-negative number to confirm.');return;}applyPatch(a.key,{[p.field]:Number(v)},`Confirmed ${E.labels[p.field]}: ${p.raw} → ${v}`);toast('Correction confirmed. Application reassessed.');}else if(d.rejectCorrection){let a=state.apps.find(a=>a.key===d.rejectCorrection),p=a.pending[Number(d.index)];applyPatch(a.key,{[p.field]:null},`Marked ${E.labels[p.field]} as missing`);}else if(el.id==='load-demo'){if(confirm('Replace this browser’s workspace with synthetic demo data? Export a backup first if needed.'))loadDemo();}else if(el.id==='restore')$('#restore-file').click();else if(el.id==='export')exportModal();else if(el.id==='export-json')download('franchise-workspace.json',JSON.stringify({version:1,state},null,2),'application/json');else if(el.id==='export-csv'){const safe=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};let rows=[['Application ID','Name','City','Pin','Decision','Internal status','Recorded-input score','Possible score','Grade','Model','Legacy score','Territory','One-line reason','Next step','Reasons','Next action'],...results.map(a=>[a.id,a.name,a.city,a.pin,dec(a).label,a.status,a.score,a.high,a.grade,a.model,a.legacyScore,a.territory,dec(a).headline,dec(a).next,a.reasons.join(' '),nextAction(a)])];download('franchise-assessments.csv','\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8');}else if(el.id==='confirm-chat'){let p=pendingChat;let current=p&&state.apps.find(a=>a.key===p.key);if(!current||JSON.stringify(E.fields.map(f=>current[f]))!==p.snapshot){pendingChat=null;chat.push({text:'The application changed after this proposal. Please describe the update again so I can assess the current data.'});render();return;}pendingChat=null;if(!Object.keys(p.patch).length){chat.push({text:'Nothing to apply yet. Tell me whether the site is owned or rented and its size in sq ft.'});save();render();return;}let prev=results;applyPatch(p.key,p.patch,'Confirmed bot update: '+Object.keys(p.patch).map(f=>E.labels[f]).join(', '));let summary=FranchiseBot.changeSummary(prev,results,p.key);chat.push({text:`Confirmed and reassessed.\n${summary.text}`});save();render();$('#chat-log').scrollTop=$('#chat-log').scrollHeight;}else if(el.id==='cancel-chat'){pendingChat=null;chat.push({text:'Update cancelled. Application retained as it was.'});save();render();}else if(el.id==='confirm-import'&&importPreview){replaceWorkspace(importPreview);toast('Import complete. Every application is retained.');}else if('loadSample'in d)loadSample();else if(el.id==='help'){modal(`<div class="drawer-head"><h2>How Right Pin works</h2><button class="close" data-close aria-label="Close dialog">×</button></div><ol class="help-list"><li>Upload the supplied XLSX format. Row 3 examples are excluded unless selected.</li><li>Confirm proposed cleaning and fill missing fields.</li><li>Review scores and territory recommendations.</li><li>Ask the assistant for a reason or confirm a field update.</li><li>Verify funding, inspect the site and track opening readiness.</li></ol><div class="info-row">Data stays in this browser. Export a JSON backup to preserve your work or use another device. Other visitors have separate workspaces. The assistant uses supported rules and patterns; it does not call an external AI model.</div>`);}});
document.addEventListener('submit',e=>{if(e.target.id!=='edit-form')return;e.preventDefault();let form=e.target,patch=Object.fromEntries(new FormData(form));for(let f of E.numeric)patch[f]=patch[f]===''?null:Number(patch[f]);for(let f of E.fields)if(!E.numeric.includes(f))patch[f]=patch[f].trim()||null;applyPatch(form.dataset.key,patch,'Confirmed application details');detail(form.dataset.key);toast('Application updated. All affected allocations reassessed.');});
document.addEventListener('change',e=>{let d=e.target.dataset;if(d.task){let key=d.task,i=Number(d.taskIndex);state.tasks[key]??={};state.tasks[key][i]=e.target.checked;if(!e.target.checked)for(let j=i+1;j<7;j++)state.tasks[key][j]=false;audit(`${state.apps.find(a=>a.key===key)?.id}: ${taskDefs[i][0]} ${e.target.checked?'completed':'reopened; later steps reset'}.`);save();render();detail(key);}else if(d.taskDate){state.taskDates[d.taskDate]??={};state.taskDates[d.taskDate][d.taskIndex]=e.target.value;save();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();let r=e.target.closest('tr[data-detail]');if(r&&e.key==='Enter')detail(r.dataset.detail);if(e.key==='Tab'&&!$('#overlay').hidden){let f=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href],summary')].filter(x=>!x.disabled&&x.offsetParent!==null);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0]?.focus();}}});
$('#overlay').onclick=e=>{if(e.target===$('#overlay'))close();};$('#file').onchange=e=>parseFile(e.target.files[0]);$('#restore-file').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>10000000)throw Error('Backup is too large.');let p=JSON.parse(await f.text());if(p.version!==1||!E.validState(p.state))throw Error('This is not a valid Right Pin backup.');E.assess(p.state.apps,p.state.territories,stores,p.state.reference,p.state.settings);if(!confirm('Replace this browser’s workspace with the backup?'))return;pendingChat=null;chat=[];botContext=null;state=p.state;if(state.settings.model!=='industry-v2')state.settings={...E.defaultPolicy,...Object.fromEntries(Object.entries(state.settings).filter(([k,v])=>v!=='')),model:'industry-v2'};state.taskDates??={};state.tasks??={};state.audit??=[];state.warnings??=[];audit('Restored workspace from a JSON backup.');save();close();tab='decisions';location.hash=tab;render();toast('Backup restored.');}catch(err){toast(err.message||'Backup could not be restored.');}e.target.value='';};
window.addEventListener('hashchange',()=>{tab=location.hash.slice(1)||defaultTab();render();});
(async()=>{try{const s=localStorage.getItem('franchise-os-v1');if(s){let p=JSON.parse(s);if(E.validState(p)){state=p;if(state.settings.model!=='industry-v2'){state.settings={...E.defaultPolicy,...Object.fromEntries(Object.entries(state.settings).filter(([k,v])=>v!=='')),model:'industry-v2'};audit('Rescored with industry-informed v2 screening using the labelled illustrative retail requirements.');}state.taskDates??={};chat=Array.isArray(state.messages)?state.messages:[];botContext=state.botContext||null;tab=location.hash.slice(1)||defaultTab();render();return;}}}catch(e){storageOK=false;}await loadDemo(true);})();
